package com.bank.ops;

import java.util.*;
import java.util.logging.*;

public class SlidingMaxDemo {
    private static final Logger log = Logger.getLogger(SlidingMaxDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        PeakRateAnalyzer analyzer = new PeakRateAnalyzer();

        int[] rates = {1, 3, -1, -3, 5, 3, 6, 7}; // txns/min deltas
        int[] peaks = analyzer.rollingMax(rates, 3);
        log.info(() -> "Rolling window maxima (k=3): " + Arrays.toString(peaks));
    }
}

