class PeakRateAnalyzer {
    private static final Logger log = Logger.getLogger(PeakRateAnalyzer.class.getName());

    // Monotonic decreasing deque of indices. O(n) time, O(k) space.
    int[] rollingMax(int[] a, int k) {
        if (a.length == 0 || k <= 0) return new int[0];
        Deque<Integer> dq = new ArrayDeque<>(); // holds INDICES, values decreasing
        int[] out = new int[a.length - k + 1];
        for (int r = 0; r < a.length; r++) {
            while (!dq.isEmpty() && a[dq.peekLast()] <= a[r]) {
                dq.pollLast();                 // smaller/equal can't be max while a[r] present
            }
            dq.offerLast(r);
            if (dq.peekFirst() <= r - k) {
                dq.pollFirst();                // front slid out of window
            }
            if (r >= k - 1) {
                out[r - k + 1] = a[dq.peekFirst()]; // front = window max
            }
        }
        return out;
    }
}

